  "version": "1.0.0",
  "description": "Resolve symlinks in a path to its canonical filesystem path, consistently across Node versions",
  "type": "module",
  "main": "src/realpath.js",
  "bin": {
    "realpath-resolve": "src/cli.js"
  },
  "scripts": {
    "start": "node src/cli.js",
    "test": "node --test test/"
  },
  "engines": {
    "node": ">=18"
  },
  "license": "MIT"
}
EOF
cat > src/realpath.js <<'EOF'
import fs from 'node:fs';
import path from 'node:path';

// Node ships two realpath implementations:
//   - fs.realpath / fs.realpathSync: a JavaScript re-implementation that walks
//     each path segment with lstat/readlink. Its behavior has shifted between
//     Node versions and differs from the OS (e.g. Windows drive-letter casing,
//     subst drives, junctions, named pipes).
//   - fs.realpath.native / fs.realpathSync.native / fs.promises.realpath:
//     delegate to libuv's uv_fs_realpath, i.e. the OS realpath(3) /
//     GetFinalPathNameByHandle. This is what the kernel considers canonical.
// We always use the native variant so results match the OS and stay stable
// across Node releases.

/**
 * Resolve `p` (relative to process.cwd() if not absolute) to its canonical
 * path with all symlinks, `.` and `..` segments resolved.
 * Rejects with ENOENT if any component does not exist.
 * @param {string} p
 * @returns {Promise<string>}
 */
export async function resolveRealPath(p) {
  return fs.promises.realpath(path.resolve(p));
}

/**
 * Synchronous variant of {@link resolveRealPath}.
 * @param {string} p
 * @returns {string}
 */
export function resolveRealPathSync(p) {
  return fs.realpathSync.native(path.resolve(p));
}
EOF
cat > src/cli.js <<'EOF'
#!/usr/bin/env node
import { resolveRealPath } from './realpath.js';

const args = process.argv.slice(2);
if (args.length === 0) {
  console.error('Usage: realpath-resolve <path> [path...]');
  process.exit(2);
}

let failed = false;
for (const arg of args) {
  try {
    console.log(await resolveRealPath(arg));
  } catch (err) {
    console.error(`${arg}: ${err.code ?? err.message}`);
    failed = true;
  }
}
process.exitCode = failed ? 1 : 0;
EOF
chmod +x src/cli.js
cat > test/realpath.test.js <<'EOF'
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { resolveRealPath, resolveRealPathSync } from '../src/realpath.js';

let root;

before(() => {
  // The tmpdir itself may be a symlink (e.g. /tmp -> /private/tmp on macOS),
  // so canonicalize it first.
  root = fs.realpathSync.native(fs.mkdtempSync(path.join(os.tmpdir(), 'rp-')));
  fs.mkdirSync(path.join(root, 'real', 'nested'), { recursive: true });
  fs.writeFileSync(path.join(root, 'real', 'nested', 'file.txt'), 'x');
  fs.symlinkSync(path.join(root, 'real'), path.join(root, 'link-dir'), 'dir');
  fs.symlinkSync('link-dir', path.join(root, 'link-to-link'), 'dir');
  fs.symlinkSync(path.join(root, 'missing'), path.join(root, 'dangling'));
});

after(() => fs.rmSync(root, { recursive: true, force: true }));

const expected = () => path.join(root, 'real', 'nested', 'file.txt');

test('resolves a directory symlink in the middle of a path', async () => {
  const p = path.join(root, 'link-dir', 'nested', 'file.txt');
  assert.equal(await resolveRealPath(p), expected());
  assert.equal(resolveRealPathSync(p), expected());
});

test('resolves chained relative symlinks', async () => {
  const p = path.join(root, 'link-to-link', 'nested', 'file.txt');
  assert.equal(await resolveRealPath(p), expected());
});

test('normalizes . and .. segments', async () => {
  const p = path.join(root, 'link-dir', 'nested', '..', 'nested', '.', 'file.txt');
  assert.equal(await resolveRealPath(p), expected());
});

test('resolves relative paths against cwd', async () => {
  const cwd = process.cwd();
  process.chdir(root);
  try {
    assert.equal(await resolveRealPath('link-dir/nested/file.txt'), expected());
  } finally {
    process.chdir(cwd);
  }
});

test('rejects with ENOENT for dangling symlinks and missing paths', async () => {
  await assert.rejects(resolveRealPath(path.join(root, 'dangling')), { code: 'ENOENT' });
  assert.throws(() => resolveRealPathSync(path.join(root, 'nope')), { code: 'ENOENT' });
});
EOF
cat > .gitignore <<'EOF'
node_modules/
EOF
npm test 2>&1 | tail -15; ln -sfn /work/src /tmp/srclink && node src/cli.js /tmp/srclink/cli.js /tmp/nope; echo "exit=$?"

